// The Idle Adventure's areas (README: Idle Adventure): Kanto's main road in the game's order, from Route 1 to the
// Champion's room, then the places off it (WalkArea.opens), generated by tools/idle/kanto_areas.py (data/gen1/areas.ts, maps.ts). A route, dungeon, gym or
// League room is legs walked along their planned tracks (one fade between legs); a town is where the run waits for the
// player's choice (gym, store, continue).
import { generation, perGeneration } from './generation.js';

/** A FireRed or HeartGold map an area walks: its picture (in apps/web/public) and size in 16px tiles, its wild table, battle scene and music. */
export interface IdleMap {
  name: string;
  image: string;
  width: number;
  height: number;
  /** Its wild encounter table (ENCOUNTERS' key). */
  encounters: string;
  /** Its map battle scene (MAP_BATTLE_SCENE_, lower case): gym, lorelei… for the battle background. */
  scene: string;
  /** Its song (the game's MUS_ constant; HGSS's SEQ_ one, by day). */
  music: string;
  /** HGSS's song by night, where it differs. */
  nightMusic?: string;
  /**
   * What's drawn over the player while he's under it (the user's, 2026-11-04: Goldenrod Gym's bridges, walked over and
   * then under): its picture, over him on a track's steps flagged 8, and the tiles it covers (left, top, right, bottom).
   */
  overhead?: string;
  bridges?: [number, number, number, number][];
  /**
   * What FireRed draws over the people on its map (its top background layer: a tree's top, a counter's near edge; the
   * user's: the treetops masking the player, as the run maps' Kanto routes draw them), always over every sprite: a
   * picture the map's size, see-through elsewhere (tools/routes/kanto_overheads.py). None on a map without.
   */
  top?: string;
  /** Its Town Map section (MAPSEC_, lower case: TownMapPlace.section): the Town Map offers a place its own maps' grinds. */
  section: string;
  /** Its walking heights (HGSS's maps that aren't flat: data/gen2/heights.ts), the sprites raised by them (mapLift). None on a flat map or FireRed's. */
  heights?: MapHeights;
}

/**
 * A HeartGold map's walking heights (tools/idle/hgss_render.py's heights.ts, README: Idle Adventure, Johto's heights):
 * its picture is drawn from the 3D map tilted, the ground at `ground` on the tile grid and anything higher or lower
 * HGSS_TILT game pixels further up or down a model unit (16 a tile), so a sprite stands raised by its tile's height above
 * it, as HGSS stands people at their 3D height. In model units above `ground`: each tile's (`rows`, a letter each, its
 * index in `levels` (LEVEL_CHARS), in runs: 'a12b3' 12 tiles of the first, 3 of the second) and a tile's others (`also`:
 * [x, y, height], a bridge's and the path's under it).
 */
export interface MapHeights {
  ground: number;
  levels: number[];
  rows: string[];
  also?: [number, number, number][];
}

/** How far up the HGSS pictures draw a model unit higher, in game pixels (tools/routes/hgss/render_hgss.py's tilt). */
export const HGSS_TILT = 0.6;
const LEVEL_CHARS = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';

/** Each map's rows of tile heights, their runs read out once (by its MapHeights). */
const unpacked = new WeakMap<MapHeights, number[][]>();

function tileHeights(heights: MapHeights): number[][] {
  let rows = unpacked.get(heights);
  if (!rows) {
    rows = heights.rows.map((row) => [...row.matchAll(/([a-zA-Z])(\d*)/g)].flatMap(([, c, n]) => Array<number>(n ? Number(n) : 1).fill(heights.levels[LEVEL_CHARS.indexOf(c!)]!)));
    unpacked.set(heights, rows);
  }
  return rows;
}

/**
 * How far up a sprite standing on tile (x, y) is drawn, in whole game pixels (16 a tile): its height above the map's
 * picture's ground (MapHeights), 0 on a flat map or off it. On a tile with several heights (a bridge over a path), the
 * one nearest `from` (the lift of the tile it came from), as HGSS takes the nearest to a person's own height.
 */
export function mapLift(heights: MapHeights | undefined, x: number, y: number, from?: number): number {
  if (!heights) return 0;
  const height = tileHeights(heights)[y]?.[x];
  if (height === undefined) return 0;
  const lift = (h: number) => Math.round(h * HGSS_TILT);
  const own = lift(height);
  if (from === undefined || !heights.also) return own;
  return heights.also.filter(([ax, ay]) => ax === x && ay === y).reduce((best, [, , h]) => (Math.abs(lift(h) - from) < Math.abs(best - from) ? lift(h) : best), own);
}

/**
 * A step of a track: the map (its index in the leg's maps), the tile, flags (1: reached through a fade, a warp or a
 * gatehouse; 2: jumped onto over a ledge; 4: slid onto across ice, HGSS's maps; 8: under the map's overhead, Goldenrod
 * Gym's bridges) and the tile's wild encounters ('l' land, 'w' water, '.' none) and battle
 * terrain (Terrain's first letter: g grass, s sand, w water, p pond, m mountain, c cave, b building, '.' plain; HGSS's n snow, i ice).
 */
export type TrackStep = [map: number, x: number, y: number, flags: number, tile: string];

export type Facing = 'up' | 'down' | 'left' | 'right';

export interface AreaTrainer {
  /** TRAINERS' key ('champion' for Blue: the run picks his team). */
  key: string;
  leg: number;
  map: number;
  x: number;
  y: number;
  face: Facing;
  /** Their overworld sprite (public/overworld/<sprite>.png). */
  sprite: string;
  /** The tiles they see (stepping onto one starts the battle). */
  sight: [number, number][];
  /** Standing in tall grass: its grass drawn over their feet (TallGrass). */
  grass?: true;
  /** HGSS's: there only at night, or only by day, by the run's clock (the user's, 2026-11-04: Policemen Keith and Dirk only at night). */
  night?: true;
  day?: true;
}

export interface IdleLeg {
  maps: string[];
  track: TrackStep[];
}

export interface WalkArea {
  id: string;
  name: string;
  kind: 'route' | 'dungeon' | 'gym' | 'league';
  legs: IdleLeg[];
  /** Its trainers, in the order the track meets them. */
  trainers: AreaTrainer[];
  /** A gym's town (back there once it's beaten), badge and leader; a League room's boss. */
  town?: string;
  badge?: string;
  leader?: string;
  /**
   * Off the main road (the user's, 2026-10-27): the area whose reaching opens it on the Town Map. Never walked on to nor
   * progress; only grinded in, the run going back to its furthest place when it walks off the end.
   */
  opens?: string;
  /**
   * A legendary Pokémon at the track's end (the user's, 2026-10-27: picked on the Town Map once the run reaches the
   * Indigo Plateau, `opens`): its species and level, where it stands (map index in the leg, tile, facing) and its
   * overworld sprite. The run walks up to it and battles it; beaten or caught, it's gone for the run (IdleState.legends).
   */
  legend?: { species: number; level: number; map: number; x: number; y: number; face: Facing; sprite: string };
  /**
   * Where it fishes (the user's, 2026-10-27: a wild grind with a rod), one a map with fishing: the leg, the step of its
   * track nearest the spot (the run's place while it fishes, faded from), the way the player faces the water and the
   * tile they stand on (on the shore, or surfing where nothing on land faces any: a 1 after).
   */
  fishing?: [leg: number, step: number, face: Facing, x: number, y: number, surfing?: 1][];
}

export interface TownArea {
  id: string;
  name: string;
  kind: 'town';
  map: string;
  /** Where the player stands (before the Pokémon Center). */
  stand: [number, number];
  /** Its marts' lists (MARTS' keys). */
  marts: string[];
  /** Its gym's area, or the League's first room (none in Viridian City the first time, Lavender Town). */
  gym?: string;
  /**
   * Its Poké Mart (the store, the user's): the map its first list is sold on, the player's tile across the counter from
   * the clerk who sells it and the way they face, and everyone there as the map places them (the clerk facing the player).
   */
  mart: { map: string; x: number; y: number; face: 'up' | 'down' | 'left' | 'right'; people: { sprite: string; x: number; y: number; face: 'up' | 'down' | 'left' | 'right' }[] };
  /**
   * Where a run grinds before its gym (the user's): a loop round a ring of wild encounter tiles near the exit of the area
   * before the town (its last leg with wild Pokémon), each step a track's, walked round and round from the first.
   */
  grind?: { area: string; leg: number; loop: TrackStep[] };
}

export type IdleArea = WalkArea | TownArea;

/** The active generation's areas, in order (IdleState.area is an index into them). */
export const areas = (): readonly IdleArea[] => generation().areas;

export function areaById(id: string): IdleArea {
  const a = areas().find((x) => x.id === id);
  if (!a) throw new Error(`Unknown area ${id}`);
  return a;
}

export const areaIndex = (id: string) => areas().findIndex((a) => a.id === id);

export function mapView(name: string): IdleMap {
  const m = generation().maps[name];
  if (!m) throw new Error(`Unknown map ${name}`);
  return m;
}

export const isTown = (a: IdleArea): a is TownArea => a.kind === 'town';

/** Whether an area is off the main road (WalkArea.opens: Route 11, the Safari Zone…). */
export const isOptional = (index: number) => !!(areas()[index] as WalkArea | undefined)?.opens;

/** An area's legendary Pokémon (WalkArea.legend), if it has one. */
export const legendOf = (index: number) => (areas()[index] as WalkArea | undefined)?.legend ?? null;

/** Whether a run that has reached `reached` (areas()' index, the main road's) can go to an area: a main-road one up to it, an optional one once its `opens` is. */
export function areaOpen(index: number, reached: number): boolean {
  const a = areas()[index];
  if (!a) return false;
  return isOptional(index) ? areaIndex((a as WalkArea).opens!) <= reached : index <= reached;
}

/** The terrain letters of a track step's tile. */
export const TERRAIN_LETTERS = { g: 'grass', s: 'sand', w: 'water', p: 'pond', m: 'mountain', c: 'cave', b: 'building', n: 'snow', i: 'ice', '.': 'plain' } as const;

/** The badges in order (each gym's), for the run's badge count and FireRed's badge boosts. */
export const badgeList = perGeneration((g) => g.areas.filter((a): a is WalkArea => a.kind === 'gym').map((a) => a.badge!));
